'use strict';
const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const Module = require('module');
const nconf = require('nconf');

(async () => {
	const root = fs.mkdtempSync(path.join(os.tmpdir(), 'nodebb-group-cover-'));
	const uploadRoot = path.join(root, 'uploads');
	const filesRoot = path.join(uploadRoot, 'files');
	fs.mkdirSync(filesRoot, { recursive: true });
	nconf.set('upload_path', uploadRoot);
	nconf.set('relative_path', '/forum');

	const cover = path.join(filesRoot, 'groupCover-Test.png');
	const thumb = path.join(filesRoot, 'groupCoverThumb-Test.png');
	const outside = path.join(root, 'outside.png');
	fs.writeFileSync(cover, 'cover');
	fs.writeFileSync(thumb, 'thumb');
	fs.writeFileSync(outside, 'outside');

	const fields = {
		'cover:url': '/forum/assets/uploads/files/groupCover-Test.png',
		'cover:thumb:url': '/forum/assets/uploads/files/groupCoverThumb-Test.png',
		'cover:position': '50% 50%',
	};
	const database = {
		getObjectFields: async () => ({ ...fields }),
		deleteObjectFields: async (_key, names) => names.forEach(name => delete fields[name]),
	};
	const originalLoad = Module._load;
	Module._load = function (request, parent, isMain) {
		if (parent && parent.filename.endsWith('/src/groups/cover.js')) {
			if (request === '../database') { return database; }
			if (request === '../image') { return {}; }
			if (request === '../file') { return {}; }
		}
		return originalLoad.call(this, request, parent, isMain);
	};
	let Groups;
	try {
		Groups = {};
		require('./src/groups/cover')(Groups);
	} finally {
		Module._load = originalLoad;
	}
	await Groups.removeCover({ groupName: 'Test' });
	assert.deepStrictEqual(fields, {});
	assert.strictEqual(fs.existsSync(cover), false);
	assert.strictEqual(fs.existsSync(thumb), false);

	fields['cover:url'] = '/forum/assets/uploads/files/../outside.png';
	fields['cover:thumb:url'] = 'https://example.com/forum/assets/uploads/files/nope.png';
	await Groups.removeCover({ groupName: 'Test' });
	assert.strictEqual(fs.existsSync(outside), true);
	await Groups.removeCover({ groupName: 'Test' });
	fs.rmSync(root, { recursive: true, force: true });
	process.stdout.write('group cover cleanup fixture passed\\n');
})().catch((err) => {
	process.stderr.write(err.stack + '\\n');
	process.exitCode = 1;
});
NODE`;
